+test("基底色空間の循環は警告にして無限再帰を避ける", async () => {
+  const result = await executeColorSpace({
+    resources: "<< /ColorSpace << /Cycle 1 0 R >> >>",
+    objects: ["[/Pattern 1 0 R]"],
+    content: "/Cycle cs",
